{"command":"ss -ltn 2>/dev/null | grep -E '806[0-9]' ; python3 -c "
import socket
for p in (8060, 8061, 8062):
    s = socket.socket()
    try:
        s.bind(('127.0.0.1', p)); print(p, 'free')
    except OSError as e:
        print(p, 'in use')
    finally:
        s.close()
""}
